#!/usr/bin/env tsx

import fs from 'node:fs/promises';
import path from 'node:path';

import { WINES } from './seed-wines-real.js';

const OUTPUT_PATH = path.resolve(
  process.cwd(),
  'src/domain/attribute/service/generated/seeded-korean-entity-alias-catalog.ts',
);
const HANGUL_RE = /[\uAC00-\uD7AF\u1100-\u11FF\u3130-\u318F]/u;
const WHITESPACE_RE = /\s+/gu;
const GENERATED_HEADER = `/**
 * Generated by scripts/generate-seeded-korean-entity-alias-catalog.ts.
 *
 * Source: scripts/seed-wines-real.ts
 * Contract:
 * - Hangul-containing aliases only
 * - unique normalized surface -> single entity
 * - exact identity aliases only (aliasesIdentitySafe)
 * - exportToDefaultMappings=false so non-ontology wine labels never leak into
 *   structured planner constraints
 */

export interface SeededKoreanEntityAliasCatalogEntry {
  readonly surface: string;
  readonly mappedAttribute: 'appellation';
  readonly canonicalValue: string;
  readonly mappingConfidence: number;
  readonly provenance: 'seed_catalog';
  readonly resolutionMode: 'direct';
  readonly exportToDefaultMappings: false;
}

export const SEEDED_KOREAN_ENTITY_ALIAS_CATALOG: readonly SeededKoreanEntityAliasCatalogEntry[] = [
`;
const GENERATED_FOOTER = `] as const;
`;
const GENERATED_CONFIDENCE = 0.94;

function normalizeSurface(surface: string): string {
  return surface.normalize('NFKC').toLowerCase().replace(WHITESPACE_RE, ' ').trim();
}

interface AliasOwner {
  readonly surface: string;
  readonly canonicalValue: string;
  readonly entityId: string;
}

async function run(): Promise<void> {
  const owners = new Map<string, AliasOwner[]>();

  for (const wine of WINES) {
    const canonicalValue = wine.canonicalLabel.trim();
    if (canonicalValue.length === 0) {
      continue;
    }

    for (const alias of wine.aliasesIdentitySafe ?? []) {
      if (!HANGUL_RE.test(alias)) {
        continue;
      }

      const surface = alias.trim();
      if (surface.length === 0) {
        continue;
      }

      const normalized = normalizeSurface(surface);
      const existing = owners.get(normalized) ?? [];
      existing.push({
        surface,
        canonicalValue,
        entityId: String(wine.entityId),
      });
      owners.set(normalized, existing);
    }
  }

  const uniqueEntries = [...owners.entries()]
    .map(([, aliasOwners]) => {
      const entityIds = [...new Set(aliasOwners.map((entry) => entry.entityId))];
      if (entityIds.length !== 1) {
        return null;
      }
      return aliasOwners[0] ?? null;
    })
    .filter((entry): entry is AliasOwner => entry !== null)
    .sort((left, right) => {
      const byCanonical = left.canonicalValue.localeCompare(right.canonicalValue, 'en');
      if (byCanonical !== 0) {
        return byCanonical;
      }
      return left.surface.localeCompare(right.surface, 'ko');
    });

  const lines = uniqueEntries.map((entry) =>
    `  { surface: ${JSON.stringify(entry.surface)}, mappedAttribute: 'appellation', canonicalValue: ${JSON.stringify(entry.canonicalValue)}, mappingConfidence: ${GENERATED_CONFIDENCE}, provenance: 'seed_catalog', resolutionMode: 'direct', exportToDefaultMappings: false },`,
  );

  const content = `${GENERATED_HEADER}${lines.join('\n')}\n${GENERATED_FOOTER}`;
  await fs.mkdir(path.dirname(OUTPUT_PATH), { recursive: true });
  await fs.writeFile(OUTPUT_PATH, content, 'utf8');
  console.log(`Wrote ${uniqueEntries.length} seeded Korean exact aliases to ${OUTPUT_PATH}`);
}

void run().catch((error: unknown) => {
  const message = error instanceof Error ? error.stack ?? error.message : String(error);
  console.error(message);
  process.exit(1);
});
